using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;
namespace OpenAntiLag {
 public class ToolPage:TabPage {
  protected readonly FlowLayoutPanel Header=new FlowLayoutPanel {Dock=DockStyle.Top,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false,Padding=new Padding(4)};
  protected readonly TextBox Output=new TextBox {Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,Dock=DockStyle.Fill,BackColor=Theme.Background,ForeColor=Theme.Text,BorderStyle=BorderStyle.None,WordWrap=true};
  protected readonly Label Status=new Label {Name="toolStatus",AutoSize=true,ForeColor=Theme.Muted,Margin=new Padding(4,6,4,8)};
  public event Action<string,bool> OperationCompleted;
  protected readonly bool Preview;protected bool Working;protected CancellationTokenSource CancelSource;
  readonly List<Button> actions=new List<Button>();readonly HashSet<Button> restricted=new HashSet<Button>();readonly Func<bool> acquire;readonly Action release;readonly ProfileButton cancel=new ProfileButton {Name="stopTool",Text="Остановить",Height=38,Width=150};
  public ToolPage(string title,bool preview,Func<bool> acquire=null,Action release=null):base(title){Preview=preview;this.acquire=acquire??(()=>true);this.release=release??(()=>{});BackColor=Theme.Background;ForeColor=Theme.Text;Padding=new Padding(12);var root=new TableLayoutPanel {Dock=DockStyle.Fill,ColumnCount=1,RowCount=2};root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Percent,58));root.RowStyles.Add(new RowStyle(SizeType.Percent,42));var scroll=new Panel {Dock=DockStyle.Fill,AutoScroll=true};scroll.Controls.Add(Header);root.Controls.Add(scroll,0,0);root.Controls.Add(Output,0,1);Controls.Add(root);Header.Controls.Add(Status);Header.Controls.Add(cancel);cancel.Enabled=false;cancel.Click+=delegate{if(CancelSource!=null)CancelSource.Cancel();};Output.HandleCreated+=delegate{WindowTheme.Scrollbar(Output.Handle);};scroll.HandleCreated+=delegate{WindowTheme.Scrollbar(scroll.Handle);};Header.SizeChanged+=delegate{foreach(var label in Header.Controls.OfType<Label>())label.MaximumSize=new Size(Math.Max(120,Header.ClientSize.Width-32),0);};Status.Text=preview?"Предпросмотр: операции отключены.":"Действия запускаются только по кнопке.";}
  protected Label Note(string text){var label=new Label {Text=text,AutoSize=true,ForeColor=Theme.Muted,MaximumSize=new Size(650,0),Margin=new Padding(4,5,4,8)};Header.Controls.Add(label);return label;}
  protected FlowLayoutPanel Row(params Control[] controls){var row=new FlowLayoutPanel {AutoSize=true,FlowDirection=FlowDirection.LeftToRight,WrapContents=true,Dock=DockStyle.Top,Margin=new Padding(0,3,0,3)};foreach(var control in controls)row.Controls.Add(control);Header.Controls.Add(row);return row;}
  protected Label Caption(string text){return new Label {Text=text,AutoSize=true,Margin=new Padding(4,7,4,3)};}
  protected TextBox Field(string text,int width){return new TextBox {Text=text,Width=width,BackColor=Theme.Surface,ForeColor=Theme.Text,BorderStyle=BorderStyle.FixedSingle};}
  protected ComboBox Choice(int width){return new ThemedComboBox {DropDownStyle=ComboBoxStyle.DropDownList,Width=width};}
  protected NumericUpDown Number(decimal min,decimal max,decimal value,int width=80){return new ThemedNumericUpDown {Minimum=min,Maximum=max,Value=value,Width=width};}
  protected ProfileButton ActionButton(string text,Func<CancellationToken,Task> action,bool mutation=false){var button=new ProfileButton {Name=text,Text=text,Width=210,Height=42,Enabled=!Preview};actions.Add(button);button.Click+=async delegate{await Work(action,mutation);};return button;}
  protected void RestrictNamed(string name){foreach(var button in actions.Where(b=>b.Text==name))Restrict(button);}
  protected void Restrict(Button button){if(button!=null){restricted.Add(button);button.Enabled=false;}}
  static IEnumerable<Control> Inputs(Control root){foreach(Control child in root.Controls){if(child is TextBoxBase||child is ComboBox||child is CheckBox||child is NumericUpDown)yield return child;foreach(var nested in Inputs(child))yield return nested;}}
  protected async Task Work(Func<CancellationToken,Task> action,bool mutation=false){if(Preview||Working)return;if(mutation&&!acquire()){Status.Text="Дождитесь завершения другой операции применения.";return;}var inputStates=Inputs(Header).ToDictionary(c=>c,c=>c.Enabled);foreach(var control in inputStates.Keys)control.Enabled=false;Working=true;CancelSource=new CancellationTokenSource();foreach(var b in actions)b.Enabled=false;cancel.Enabled=!mutation;Status.Text=mutation?"Операция сети: подтвердите UAC. Дождитесь проверки результата; журнал сохраняется до записи.":"Операция выполняется…";try{await action(CancelSource.Token);if(!IsDisposed)Status.Text="Операция завершена.";if(OperationCompleted!=null)OperationCompleted("Операция подтверждена; результат в подробностях раздела",true);}catch(OperationCanceledException){if(!IsDisposed)Status.Text="Операция отменена. Прерванные пробы не считаются потерями.";}catch(Exception error){if(OperationCompleted!=null)OperationCompleted(error.Message,false);if(!IsDisposed){Status.Text=error.Message;Log("Не завершено: "+error.Message);}}finally{CancelSource.Dispose();CancelSource=null;Working=false;if(mutation)release();if(!IsDisposed){foreach(var b in actions)b.Enabled=!restricted.Contains(b);foreach(var control in inputStates.Keys)if(!control.IsDisposed)control.Enabled=inputStates[control];cancel.Enabled=false;}}}
  protected void OnUi(Action action){if(IsDisposed||Disposing||!IsHandleCreated)return;if(InvokeRequired){try{BeginInvoke((Action)(()=>{if(!IsDisposed)action();}));}catch(InvalidOperationException){}}else action();}
  protected void Log(string text){OnUi(delegate{if(Output.TextLength>200000)Output.Text=Output.Text.Substring(Output.TextLength-100000);Output.AppendText(text+Environment.NewLine);});}
  protected void ShowText(string text){OnUi(()=>Output.Text=text);}
  protected static string ExportPath(string title){using(var dialog=new SaveFileDialog {Title=title,Filter="CSV (*.csv)|*.csv|JSON (*.json)|*.json",DefaultExt="csv"})return dialog.ShowDialog()==DialogResult.OK?dialog.FileName:null;}
  protected override void Dispose(bool disposing){if(disposing&&CancelSource!=null)CancelSource.Cancel();base.Dispose(disposing);}
 }
 public sealed class HistoryGraph:Control {
  double[] values=new double[0];public HistoryGraph(){DoubleBuffered=true;BackColor=Theme.Surface;ForeColor=Theme.Accent;Height=110;Dock=DockStyle.Bottom;}
  public void SetValues(IEnumerable<double> source){var all=source.ToArray();values=all.Skip(Math.Max(0,all.Length-300)).ToArray();Invalidate();}
  protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(values.Length<2||Width<10||Height<10)return;double max=Math.Max(1,values.Max());using(var pen=new Pen(Theme.Accent,2)){var points=values.Select((v,i)=>new PointF(4+(Width-8)*i/(float)(values.Length-1),Height-4-(float)(v/max)*(Height-20))).ToArray();e.Graphics.DrawLines(pen,points);}TextRenderer.DrawText(e.Graphics,"0–"+max.ToString("0.0"),Font,new Point(4,2),Theme.Muted);}
 }
 public sealed class NetworkPage:ToolPage {
  readonly NetworkMonitor monitor;readonly TextBox target,summary;readonly NumericUpDown interval,duration,highRtt,highJitter;readonly CheckBox gateway,dns,tcp,consent,watchGames;readonly ComboBox processes,endpoints,profiles;readonly TextBox gameName,profileExclusions;readonly System.Windows.Forms.Timer watcher=new System.Windows.Forms.Timer {Interval=3000};readonly HistoryGraph graph=new HistoryGraph();string activeTarget;GameNetworkProfile profile=GameProfileManager.Defaults()[0];bool watchedRunning;int watchedPid;CancellationTokenSource gameMonitor;
  public NetworkPage(bool preview,NetworkMonitor monitor=null):base("Сеть",preview){this.monitor=monitor??new NetworkMonitor();Name="networkPage";Note("Только локальная диагностика. RTT и потери ICMP не равны ping/потерям игрового UDP. Jitter — среднее |RTTᵢ−RTTᵢ₋₁| соседних успешных проб без разрыва/смены интерфейса; σ — стандартное отклонение RTT.");target=Field("1.1.1.1",220);interval=Number(1,60,2);duration=Number(5,3600,120);highRtt=Number(1,10000,100);highJitter=Number(1,10000,20);consent=new CheckBox {Text="Разрешаю пробы к указанному адресу",AutoSize=true};gateway=new CheckBox {Text="Также шлюзы",AutoSize=true};dns=new CheckBox {Text="DNS: запрос + ICMP",AutoSize=true};tcp=new CheckBox {Text="TCP 443 fallback (не packet loss)",AutoSize=true};Row(Caption("Диагностический IP/хост"),target);Row(Caption("Интервал, с"),interval,Caption("Длительность, с"),duration);Row(Caption("Предупреждать RTT выше, мс"),highRtt,Caption("Jitter выше, мс"),highJitter);Row(consent);Row(gateway,dns,tcp);Row(ActionButton("Начать измерение",ct=>Start(ct)),ActionButton("Интерфейсы",async ct=>{var all=await Task.Run(()=>NetworkAdapters.Read(),ct);ShowText(String.Join("\r\n\r\n",all.Select(NetworkAdapters.Describe)));}),ActionButton("Экспорт сети",ct=>{string path=ExportPath("История диагностических проб");if(path!=null)ObservationHistory.Export(path,this.monitor.History.Snapshot());return Task.FromResult(0);}));
   Note("Опция DNS отправляет обычный запрос example.com выбранным DNS-серверам не чаще одного цикла из пяти. Разрешение шлюзов/DNS не означает диагностику игрового UDP.");
   summary=Field("Статистики пока нет",660);summary.Multiline=true;summary.ReadOnly=true;summary.Height=108;Header.Controls.Add(summary);
   processes=Choice(300);endpoints=Choice(300);Row(ActionButton("Процессы / соединения",async ct=>{var list=await Task.Run(()=>GameConnections.Processes(),ct);processes.Items.Clear();foreach(var item in list)processes.Items.Add(item);if(list.Length>0)processes.SelectedIndex=0;Log("Обнаружены процессы; выберите нужный и прочитайте соединения. Наличие TCP не доказывает адрес игрового сервера.");}),processes);
   Row(ActionButton("Соединения процесса",async ct=>{var process=processes.SelectedItem as GameProcess;if(process==null)throw new ArgumentException("Выберите процесс");var connections=await Task.Run(()=>GameConnections.Read(),ct);endpoints.Items.Clear();var selected=connections.Where(c=>c.ProcessId==process.Id).ToArray();foreach(var ip in selected.Where(c=>c.Protocol=="TCP"&&c.RemoteAddress!="0.0.0.0"&&c.RemoteAddress!="::").Select(c=>c.RemoteAddress).Distinct())endpoints.Items.Add(ip);if(endpoints.Items.Count>0)endpoints.SelectedIndex=0;ShowText(String.Join("\r\n",selected.Select(c=>c.Protocol+" "+c.LocalAddress+":"+c.LocalPort+" → "+(c.RemoteAddress??"неизвестен")+":"+c.RemotePort+" · "+c.State))+"\r\nUDP-таблица Windows не сообщает удалённый адрес. Данных байт/с по процессу здесь нет.");}),endpoints);
   Row(ActionButton("Выбрать адрес для проб",ct=>{if(endpoints.SelectedItem==null)throw new ArgumentException("Нет выбранного удалённого TCP-адреса");target.Text=endpoints.SelectedItem.ToString();consent.Checked=false;Log("Адрес скопирован. Пробы начнутся только после разрешения и кнопки «Начать».");return Task.FromResult(0);}));
   profiles=Choice(290);foreach(var p in GameProfileManager.Defaults())profiles.Items.Add(p);profiles.SelectedIndex=0;gameName=Field("cs2",180);profileExclusions=Field("faceitclient,faceitservice",450);watchGames=new CheckBox {Text="Мониторить при запуске выбранной игры (разрешение на адрес обязательно)",AutoSize=true};Row(Caption("Профиль"),profiles,Caption("EXE без .exe"),gameName);Row(watchGames);Row(Caption("Исключения профиля для вкладки Трафик"),profileExclusions);profiles.SelectedIndexChanged+=delegate{profile=(GameNetworkProfile)profiles.SelectedItem;gameName.Text=profile.ProcessName;target.Text=profile.DiagnosticHost;consent.Checked=false;gateway.Checked=profile.IncludeGateway;dns.Checked=profile.IncludeDns;tcp.Checked=profile.TcpFallback;profileExclusions.Text=String.Join(",",profile.Exclusions);interval.Value=profile.IntervalMs/1000;duration.Value=profile.DurationSeconds;highRtt.Value=(decimal)profile.HighRttMs;highJitter.Value=(decimal)profile.HighJitterMs;};
   Row(ActionButton("Сохранить профиль",ct=>{profile.DiagnosticHost=NetworkInput.Host(target.Text);profile.IncludeGateway=gateway.Checked;profile.IncludeDns=dns.Checked;profile.TcpFallback=tcp.Checked;profile.Exclusions=profileExclusions.Text.Split(new[]{','},StringSplitOptions.RemoveEmptyEntries).Select(x=>x.Trim()).ToArray();profile.ProcessName=gameName.Text.Trim().ToLowerInvariant();profile.IntervalMs=(int)interval.Value*1000;profile.DurationSeconds=(int)duration.Value;profile.HighRttMs=(double)highRtt.Value;profile.HighJitterMs=(double)highJitter.Value;GameProfileManager.Save(Path.Combine(Program.DataDirectory,"network-profile.json"),profile);return Task.FromResult(0);}),ActionButton("Загрузить профиль",ct=>{var saved=GameProfileManager.Load(Path.Combine(Program.DataDirectory,"network-profile.json"));profiles.Items.Add(saved);profiles.SelectedItem=saved;return Task.FromResult(0);}));
   Note("CS2 / FACEIT по умолчанию: только мониторинг. QoS/DNS не применяются профилем автоматически. Официальная совместимость с FACEIT AC не подтверждена.");
   this.monitor.Sample+=sample=>OnUi(delegate{if(sample.Target==activeTarget)summary.Text=ProbeSummary.Calculate(this.monitor.History.Snapshot().Where(s=>s.Target==activeTarget)).ToString();graph.SetValues(this.monitor.History.Snapshot().Where(s=>s.Kind=="ICMP"&&s.Success&&s.Target==target.Text).Select(s=>s.Milliseconds));Log(sample.Utc.ToLocalTime().ToString("HH:mm:ss")+" "+sample.Target+" · "+sample.Kind+" · "+sample.Detail+" · "+sample.Milliseconds.ToString("0.0")+" мс");});this.monitor.Notice+=Log;Controls.Add(graph);graph.BringToFront();watcher.Tick+=async delegate{if(Preview||!watchGames.Checked)return;try{string name=gameName.Text.Trim().ToLowerInvariant();if(name.Length==0)return;var running=await Task.Run(()=>GameConnections.Processes().FirstOrDefault(p=>p.Name.Equals(name,StringComparison.OrdinalIgnoreCase)));if(running==null){if(watchedRunning&&gameMonitor!=null)gameMonitor.Cancel();watchedRunning=false;watchedPid=0;return;}if(watchedRunning&&watchedPid==running.Id)return;if(Working||!consent.Checked)return;watchedRunning=true;watchedPid=running.Id;await Work(async ct=>{using(var linked=CancellationTokenSource.CreateLinkedTokenSource(ct)){gameMonitor=linked;try{await Start(linked.Token);}finally{gameMonitor=null;}}});}catch(Exception error){Log(error.Message);}};if(!Preview)watcher.Start();
  }
  async Task Start(CancellationToken ct){if(!consent.Checked)throw new InvalidOperationException("Разрешите диагностические пробы к выбранному адресу");activeTarget=NetworkInput.Host(target.Text);profile.HighRttMs=(double)highRtt.Value;profile.HighJitterMs=(double)highJitter.Value;await monitor.Run(new MonitorOptions {Host=target.Text,IntervalMs=(int)interval.Value*1000,DurationSeconds=(int)duration.Value,IncludeGateway=gateway.Checked,IncludeDns=dns.Checked,TcpFallback=tcp.Checked},ct);var all=await Task.Run(()=>NetworkAdapters.Read(),ct);Log(NetworkDiagnostics.Analyze(monitor.History.Snapshot(),all,profile.HighRttMs,profile.HighJitterMs));}
  protected override void Dispose(bool disposing){if(disposing){watcher.Stop();watcher.Dispose();if(gameMonitor!=null)gameMonitor.Cancel();}base.Dispose(disposing);}
 }
}
